}

import { useState, useEffect } from "react";
import { useParams } from "react-router";
import { useQuery, getShareLink } from "wasp/client/operations";
import "./Main.css";

export function SharePage() {
  const { linkId } = useParams<{ linkId: string }>();
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [isUnlocked, setIsUnlocked] = useState(false);

  // Fetch share link metadata
  const { data: shareLink, isLoading, error: queryError } = useQuery(getShareLink, {
    linkId: linkId || "",
  });

  useEffect(() => {
    if (queryError) {
      setError((queryError as any).message || "Share link has expired or is invalid");
    }
  }, [queryError]);

  if (isLoading) return <div className="loading">Loading shared file...</div>;

  const handleUnlock = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");

    try {
      // Verify password by calling the download API with query param
      const response = await fetch(`/api/download/${linkId}?password=${encodeURIComponent(password)}`);
      if (response.ok) {
        setIsUnlocked(true);
      } else {
        const data = await response.json();
        setError(data.error || "Incorrect password");
      }
    } catch (err: any) {
      setError("Failed to verify password");
    }
  };

  const downloadUrl = `/api/download/${linkId}${
    shareLink?.isPasswordProtected ? `?password=${encodeURIComponent(password)}` : ""
  }`;

  return (
    <div className="share-page-container">
      <div className="share-card">
        <h2>Shared File</h2>

        {error && (
          <div data-testid="share-error" className="error-message">
            {error}
          </div>
        )}

        {shareLink && (
          <div className="share-info">
            <p className="file-display">📄 <strong>{shareLink.fileName}</strong></p>

            {shareLink.isPasswordProtected && !isUnlocked ? (
              <form onSubmit={handleUnlock} className="unlock-form">
                <p className="help-text">This file is password-protected. Please enter the password to download.</p>
                <div className="form-group">
                  <input
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    data-testid="unlock-password-input"
                    placeholder="Enter password"
                    required
                  />
                </div>
                <button type="submit" data-testid="unlock-btn" className="btn btn-primary">
                  Unlock
                </button>
              </form>
            ) : (
              <div className="download-section">
                <p className="success-text">File is ready for download!</p>
                <a
                  href={downloadUrl}
                  data-testid="download-btn"
                  className="btn btn-success"
                  download
                >
                  Download File
                </a>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

* {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family:
    -apple-system, BlinkMacSystemFont, "Segoe UI", "Roboto", "Oxygen", "Ubuntu",
    "Cantarell", "Fira Sans", "Droid Sans", "Helvetica Neue", sans-serif;
  background-color: #f8fafc;
  color: #1e293b;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Auth Pages */
.auth-container {
  max-width: 400px;
  width: 100%;
  margin: auto;
  padding: 2.5rem;
  background: white;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  text-align: center;
}

.auth-container h2 {
  font-size: 1.8rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  color: #0f172a;
}

.auth-form {
  text-align: left;
  margin-bottom: 1.5rem;
}

.form-group {
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: #475569;
}

.form-group input {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  font-size: 1rem;
  color: #1e293b;
  background-color: #f8fafc;
  transition: border-color 0.15s ease-in-out;
}

.form-group input:focus {
  outline: none;
  border-color: #3b82f6;
  background-color: white;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: all 0.15s ease-in-out;
  text-decoration: none;
  gap: 0.5rem;
}

.btn-primary {
  background-color: #3b82f6;
  color: white;
  width: 100%;
}

.btn-primary:hover {
  background-color: #2563eb;
}

.btn-secondary {
  background-color: #e2e8f0;
  color: #334155;
}

.btn-secondary:hover {
  background-color: #cbd5e1;
}

.btn-danger {
  background-color: #ef4444;
  color: white;
}

.btn-danger:hover {
  background-color: #dc2626;
}

.btn-success {
  background-color: #10b981;
  color: white;
  text-decoration: none;
}

.btn-success:hover {
  background-color: #059669;
}

/* Dashboard Layout */
.dashboard-container {
  max-width: 1200px;
  width: 100%;
  margin: 0 auto;
  padding: 2rem;
}

.dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid #e2e8f0;
  margin-bottom: 1.5rem;
}

.dashboard-header h1 {
  font-size: 2rem;
  font-weight: 800;
  color: #0f172a;
}

.user-info {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.breadcrumb-trail {
  font-size: 1.1rem;
  color: #64748b;
  margin-bottom: 2rem;
  background: white;
  padding: 0.75rem 1.25rem;
  border-radius: 8px;
  box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1);
}

.breadcrumb-trail a {
  color: #3b82f6;
  text-decoration: none;
  font-weight: 600;
}

.breadcrumb-trail a:hover {
  text-decoration: underline;
}

.dashboard-grid {
  display: grid;
  grid-template-columns: 300px 1fr;
  gap: 2rem;
}

@media (max-width: 768px) {
  .dashboard-grid {
    grid-template-columns: 1fr;
  }
}

/* Panels */
.actions-panel {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.panel-card {
  background: white;
  padding: 1.5rem;
  border-radius: 12px;
  box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1);
}

.panel-card h3 {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: #334155;
}

.panel-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.panel-form input[type="text"],
.panel-form input[type="file"] {
  width: 100%;
  padding: 0.625rem 0.875rem;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  font-size: 0.9rem;
}

.content-panel {
  background: white;
  padding: 2rem;
  border-radius: 12px;
  box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1);
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.folders-section h2,
.files-section h2 {
  font-size: 1.4rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: #1e293b;
  border-bottom: 2px solid #f1f5f9;
  padding-bottom: 0.5rem;
}

/* Lists */
.folder-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 1rem;
}

.folder-item {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 1rem;
  transition: all 0.15s ease-in-out;
}

.folder-item:hover {
  background: #f1f5f9;
  border-color: #cbd5e1;
  transform: translateY(-1px);
}

.folder-link {
  color: #334155;
  text-decoration: none;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  word-break: break-all;
}

.file-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.file-item {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 1rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.file-name {
  font-weight: 500;
  color: #334155;
  word-break: break-all;
}

.empty-text {
  color: #94a3b8;
  font-style: italic;
}

/* Modals */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(15, 23, 42, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.modal-content {
  background: white;
  padding: 2rem;
  border-radius: 12px;
  max-width: 500px;
  width: 100%;
  box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.1);
}

.modal-content h3 {
  font-size: 1.3rem;
  margin-bottom: 1.5rem;
  color: #0f172a;
}

.modal-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.75rem;
  margin-top: 1rem;
}

.generated-link-box {
  margin-top: 1.5rem;
  padding: 1rem;
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
  border-radius: 8px;
}

.generated-link-box p {
  font-size: 0.875rem;
  font-weight: 600;
  color: #166534;
  margin-bottom: 0.5rem;
}

.share-link-text {
  font-family: monospace;
  background: white;
  padding: 0.5rem 0.75rem;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  word-break: break-all;
  font-size: 0.9rem;
  color: #1e293b;
}

/* Access Logs */
.logs-page-container {
  max-width: 800px;
  width: 100%;
  margin: 0 auto;
  padding: 2rem;
}

.logs-content {
  background: white;
  padding: 2rem;
  border-radius: 12px;
  box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1);
}

.logs-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.log-item {
  border-bottom: 1px solid #f1f5f9;
  padding-bottom: 1rem;
}

.log-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.log-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.5rem;
}

.log-file {
  font-weight: 700;
  color: #1e293b;
}

.log-time {
  font-size: 0.85rem;
  color: #64748b;
}

.log-details {
  font-size: 0.9rem;
  color: #475569;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

/* Public Share Page */
.share-page-container {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  width: 100%;
  padding: 2rem;
}

.share-card {
  background: white;
  padding: 2.5rem;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);
  max-width: 500px;
  width: 100%;
  text-align: center;
}

.share-card h2 {
  font-size: 1.8rem;
  font-weight: 800;
  margin-bottom: 1.5rem;
  color: #0f172a;
}

.file-display {
  font-size: 1.25rem;
  margin-bottom: 1.5rem;
  color: #334155;
}

.unlock-form {
  text-align: left;
}

.help-text {
  font-size: 0.95rem;
  color: #64748b;
  margin-bottom: 1rem;
  text-align: center;
}

.error-message {
  background-color: #fef2f2;
  border: 1px solid #fca5a5;
  color: #991b1b;
  padding: 0.75rem 1rem;
  border-radius: 8px;
  margin-bottom: 1.5rem;
  font-size: 0.9rem;
  font-weight: 500;
}

.success-text {
  color: #15803d;
  font-weight: 600;
  margin-bottom: 1rem;
}

.download-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}

.loading, .error {
  text-align: center;
  padding: 3rem;
  font-size: 1.2rem;
  color: #64748b;
}

